   [33]={next_id=34, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我和“克里安卡”的确有些相同之处，但我始终认为我们之间存在着不同。", msg_color="", msg_size=0, talker="克里安卡", audio="", img="arts/ui/bg/story/storybg_803.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4519", 0, 0, 9.5, 211.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [34]={next_id=35, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她热情、开朗、并且渴求自立，但我只想陪在你身边，以任何身份都心甘情愿。", msg_color="", msg_size=0, talker="克里安卡", audio="", img="arts/ui/bg/story/storybg_803.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4519", 0, 0, 9.5, 211.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
