   [53]={next_id=54, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那孩子……我去过诊治她的医院，医生说她转去了尤赞坦的医院，由于她妈妈的粉丝一直在打探她的消息，所以我费了一番波折，好不容易才打听到地址。", msg_color="", msg_size=0, talker="瑟勒研究员", audio="", img="arts/ui/bg/story/storybg_209.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [54]={next_id=55, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她一个人孤零零地住在单人病房里，她好像不认识我了，看我的眼神就像是一个陌生人……我把这可怜的孩子抱在怀里哭，她也毫无反应。", msg_color="", msg_size=0, talker="瑟勒研究员", audio="", img="arts/ui/bg/story/storybg_209.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [55]={next_id=56, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="医生说可能是她遭遇的创伤太深了……我第二天去看她的时候，她从医院里凭空消失了，尤赞坦的警察向我承诺一定会找到她。", msg_color="", msg_size=0, talker="瑟勒研究员", audio="", img="arts/ui/bg/story/storybg_209.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
