   [135]={next_id=136, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="锋锐的刀具和针管，还有各种成分和密度的营养液，再度回想起来，它们留在我皮肤上的触感是如此地清晰。", msg_color="", msg_size=0, talker="克里安卡", audio="", img="arts/ui/bg/story/storybg_9_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4519", 0, 0, 9.5, 211.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
